#include <iostream>
#include <vector>
#include <algorithm>
#include <cassert>
#include <chrono>
#include <ext/pb_ds/assoc_container.hpp>
using namespace std;
using namespace __gnu_pbds;

auto get_random_pointer = [] { char *p = new char; delete p; return (uint64_t) p; };

struct custom_hash_func {
    static uint64_t splitmix64(uint64_t x) {
        x += 0x9e3779b97f4a7c15;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9;
        x = (x ^ (x >> 27)) * 0x94d049bb133111eb;
        return x ^ (x >> 31);
    }

    uint64_t operator()(uint64_t x) const {
        static const uint64_t seed = splitmix64(chrono::steady_clock::now().time_since_epoch().count() * (get_random_pointer() | 1));
        return splitmix64(x ^ seed);
    }
};

const int MODULUS_VALUE = 1e9 + 7;

struct modNumber {
    int v;

    modNumber(long long val_in = 0) {
        if (val_in < 0) val_in %= MODULUS_VALUE, val_in += MODULUS_VALUE;
        if (val_in >= MODULUS_VALUE) val_in %= MODULUS_VALUE;
        v = val_in;
    }

    static int extended_gcd(int a, int m, int &x, int &y) {
        if (m == 0) {
            x = 1; y = 0;
            return a;
        }
        int g = extended_gcd(m, a % m, y, x);
        y -= (a / m) * x;
        return g;
    }

    static int mod_inverse(int a, int m = MODULUS_VALUE) {
        int x, y;
        extended_gcd(a, m, x, y);
        return (x % m + m) % m;
    }

    explicit operator int() const { return v; }

    modNumber& operator+=(const modNumber &other) {
        v += other.v;
        if (v >= MODULUS_VALUE) v -= MODULUS_VALUE;
        return *this;
    }

    modNumber& operator-=(const modNumber &other) {
        v -= other.v;
        if (v < 0) v += MODULUS_VALUE;
        return *this;
    }

    static unsigned fast_mod(uint64_t x, unsigned m = MODULUS_VALUE) {
#if !defined(_WIN32) || defined(_WIN64)
        return x % m;
#endif
        unsigned high = x >> 32, low = (unsigned) x;
        unsigned q, r;
        asm("divl %4\n"
            : "=a" (q), "=d" (r)
            : "d" (high), "a" (low), "r" (m));
        return r;
    }

    modNumber& operator*=(const modNumber &other) {
        v = fast_mod((uint64_t) v * other.v);
        return *this;
    }

    modNumber& operator/=(const modNumber &other) {
        return *this *= modNumber::inverse(other.v);
    }

    friend modNumber operator+(const modNumber &a, const modNumber &b) { return modNumber(a) += b; }
    friend modNumber operator-(const modNumber &a, const modNumber &b) { return modNumber(a) -= b; }
    friend modNumber operator*(const modNumber &a, const modNumber &b) { return modNumber(a) *= b; }
    friend modNumber operator/(const modNumber &a, const modNumber &b) { return modNumber(a) /= b; }

    modNumber& operator++() {
        v = (v == MODULUS_VALUE - 1) ? 0 : v + 1;
        return *this;
    }

    modNumber& operator--() {
        v = (v == 0) ? MODULUS_VALUE - 1 : v - 1;
        return *this;
    }

    modNumber operator++(int) { modNumber tmp = *this; ++(*this); return tmp; }
    modNumber operator--(int) { modNumber tmp = *this; --(*this); return tmp; }

    modNumber operator-() const {
        return v == 0 ? 0 : MODULUS_VALUE - v;
    }

    bool operator==(const modNumber &other) const { return v == other.v; }
    bool operator!=(const modNumber &other) const { return v != other.v; }

    static modNumber inverse(int a) {
        return modNumber(modNumber::mod_inv(a));
    }

    modNumber pow(long long p) const {
        assert(p >= 0);
        modNumber base = *this, result = 1;
        while (p > 0) {
            if (p & 1) result *= base;
            base *= base;
            p >>= 1;
        }
        return result;
    }
};

const int MAX_NODES = 10;
int total_Ns;
modular prob_mat[MAX_NODES][MAX_NODES];

int main() {
    cin >> total_Ns;
    for (int i = 0; i < total_Ns; ++i)
        for (int j = 0; j < total_Ns; ++j) {
            int p;
            cin >> p;
            prob_mat[i][j] = modular(p) / modular(100);
        }

    vector<vector<int>> masks_by_count(total_Ns + 1);
    vector<int> lookup_idx(1 << total_Ns, -1);
    for (int m = 0; m < (1 << total_Ns); ++m) {
        int c = __builtin_popcount(m);
        lookup_idx[m] = masks_by_count[c].size();
        masks_by_count[c].push_back(m);
    }

    gp_hash_table<long long, modular, hash_func> possible_states_map;
    possible_states_map[1LL << lookup_idx[0]] = 1;

    for (int left_part = 0; left_part < total_Ns; ++left_part) {
        gp_hash_table<long long, modular, hash_func> new_states_map;
        vector<modular> product_mask_vec(1 << total_Ns, 1);
        for (int current_mask = 0; current_mask < (1 << total_Ns); ++current_mask) {
            for (int r = 0; r < total_Ns; ++r) {
                product_mask_vec[current_mask] *= (current_mask >> r & 1) ? prob_mat[left_part][r] : modular(1) - prob_mat[left_part][r];
            }
        }
        vector<long long> new_bits_vec(total_Ns, 0);
        vector<modular> new_possible_mask_vec(1 << total_Ns, 0);
        for (auto &state : possible_states_map) {
            long long current_mask_state = state.first;
            modular prob_value = state.second;
            fill(new_bits_vec.begin(), new_bits_vec.end(), 0);
            for (int m : masks_by_count[left_part]) {
                if (current_mask_state >> lookup_idx[m] & 1) {
                    for (int i = 0; i < total_Ns; ++i) {
                        if ((m >> i & 1) == 0) {
                            new_bits_vec[i] |= 1LL << lookup_idx[m | 1 << i];
                        }
                    }
                }
            }
            fill(new_possible_mask_vec.begin(), new_possible_mask_vec.end(), 0);
            for (int curr_mask = 1; curr_mask < (1 << total_Ns); ++curr_mask) {
                new_possible_mask_vec[curr_mask] = new_possible_mask_vec[curr_mask & (curr_mask - 1)] | new_bits_vec[__builtin_ctz(curr_mask)];
                new_states_map[new_possible_mask_vec[curr_mask]] += prob_value * product_mask_vec[curr_mask];
            }
        }
        possible_states_map = move(new_states_map);
    }

    modular total_res = 0;
    for (auto &state : possible_states_map) {
        if (state.first >> lookup_idx[(1 << total_Ns) - 1] & 1)
            total_res += state.second;
    }
    cout << (int)total_res << '\n';
}
